// Use a persistent std::string* from the pool as required by the API (valid, initialized)
// Snapshot the content to validate const-correctness (function must not mutate input)
std::string original = *str;

// Call the target function with a const reference to the string
size_t result = DoStuff(*str);

// Property: DoStuff must not modify the input string (const ref contract)
FUZZ_ASSERT(*str == original, "DoStuff must not modify input string");

// Optionally stash the last result for downstream correlation; truncated to int for attribute storage
FUZZ_SET_ATTR_INT(str, "last_DoStuff", (int)(result & 0x7fffffff));

// Output handling:
// - Return the input string back to the pool by listing it as an output.
// - The size_t result is ephemeral and not managed by the object pool; we do not export it as an output.

// Validation summary:
// - Inputs: one valid std::string*; no mutation performed.
// - Outputs: the same std::string* is returned to avoid dropping ownership; result handled ephemerally.

// Construct a valid, initialized std::string* for downstream use.
// No inputs are required; we synthesize content using the fuzzer runtime.

// Generate arbitrary content (may include non-printable bytes). Size is [1, 4096].
std::string raw = FUZZ_PARAM_STR();

// Constrain size for performance as recommended (< 2048 bytes per call).
if (raw.size() > 2048) {
    raw.resize(2048);
}

// Optionally diversify layout characteristics: sometimes reserve extra capacity, sometimes shrink_to_fit.
// Note: FUZZ_PARAM macros are compile-time expanded; use them once per branch decision, not in loops.
unsigned int mode = *FUZZ_PARAM(unsigned int);
std::string built;
if ((mode % 3) == 0) {
    // Reserve a bit more to exercise capacity vs size paths.
    size_t extra = (size_t)(*FUZZ_PARAM(unsigned int) % 64);
    built.reserve(raw.size() + extra);
    built.assign(raw.data(), raw.size());
} else if ((mode % 3) == 1) {
    // Build via repeated appends to exercise growth.
    built.clear();
    size_t cut = raw.size() ? (size_t)(*FUZZ_PARAM(unsigned int) % raw.size()) : 0;
    // Ensure at least 1 byte appended to keep non-empty invariant from FUZZ_PARAM_STR.
    size_t first = cut ? cut : std::min<size_t>(raw.size(), 1);
    built.append(raw.data(), first);
    built.append(raw.data() + first, raw.size() - first);
} else {
    // Direct construct.
    built = raw;
    if ((*FUZZ_PARAM(unsigned int) & 1u) == 1u) {
        // Exercise shrink_to_fit path (may or may not actually shrink depending on implementation).
        built.shrink_to_fit();
    }
}

// Allocate the std::string on the heap and hand ownership to the fuzzer runtime via outputs.
std::string *out = nullptr;
try {
    out = new std::string(built);
} catch (...) {
    // If allocation fails or any unexpected exception occurs, bail to keep the fuzzer state consistent.
    FUZZ_BAIL();
}

// Attach useful metadata for downstream stubs.
FUZZ_SET_ATTR_INT(out, "len", (int)(out->size() & 0x7fffffff));
FUZZ_SET_ATTR_INT(out, "empty", out->empty() ? 1 : 0);
// Heuristic: mark whether content appears ASCII-printable (quick check on a prefix to limit cost).
int ascii_flag = 1;
size_t inspect = std::min<size_t>(out->size(), 256);
for (size_t i = 0; i < inspect; ++i) {
    unsigned char c = (unsigned char)(*out)[i];
    if (!(c == 9 || c == 10 || c == 13 || (c >= 32 && c <= 126))) { ascii_flag = 0; break; }
}
FUZZ_SET_ATTR_INT(out, "likely_ascii_prefix", ascii_flag);

